async () => {
const out = {};
const q = (name, val) => document.querySelector(`input[type=radio][value="${val}"]`);
const radios = [...document.querySelectorAll('input[type=radio]')];
const info = r => ({name:r.name,value:r.value,disabled:r.disabled,checked:r.checked});
const click = r => (r.closest('label')||r).click();
const size = radios.find(r=>r.value==='M'||r.value==='m');
click(size);
await new Promise(r=>setTimeout(r,300));
for (const c of ['Blue','Black','Olive']) {
  const r = [...document.querySelectorAll('input[type=radio]')].find(x=>x.value.toLowerCase()===c.toLowerCase());
  if (r && !r.disabled) { click(r); await new Promise(r=>setTimeout(r,300)); }
  out[c] = {color: r?info(r):null, sizeM: info([...document.querySelectorAll('input[type=radio]')].find(x=>x.value.toLowerCase()==='m')), text: document.querySelector('form').innerText.replace(/\n+/g,' | ')};
}
return out;
}

